AssistantMessageToolRequest(name='create', tool_call_id='function-call-645258e4-79ee-42ad-b967-81e60f8b4d31', arguments={'file_text': ':root {
    --bg-color: #121212;
    --card-bg: #1e1e1e;
    --text-primary: #e0e0e0;
    --text-secondary: #b0b0b0;
    --accent-color: #bb86fc;
    --accent-hover: #d1aaff;
    --border-color: #333333;
    --focus-outline: #03dac6;
}

body {
    background-color: var(--bg-color);
    color: var(--text-primary);
    font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
    line-height: 1.6;
    margin: 0;
    padding: 2rem;
    display: flex;
    flex-direction: column;
    align-items: center;
}

header {
    margin-bottom: 2rem;
    text-align: center;
}

h1 {
    font-size: 2.5rem;
    color: var(--accent-color);
    margin: 0;
}

main {
    width: 100%;
    max-width: 800px;
}

.sr-only {
    position: absolute;
    width: 1px;
    height: 1px;
    padding: 0;
    margin: -1px;
    overflow: hidden;
    clip: rect(0, 0, 0, 0);
    white-space: nowrap;
    border: 0;
}

.example {
    background-color: var(--card-bg);
    border: 1px solid var(--border-color);
    border-radius: 8px;
    margin-bottom: 1rem;
    overflow: hidden;
    transition: border-color 0.2s ease;
}

.example:hover {
    border-color: var(--accent-color);
}

h3 {
    margin: 0;
}

button {
    width: 100%;
    text-align: left;
    background: none;
    border: none;
    color: var(--text-primary);
    padding: 1rem 1.5rem;
    font-size: 1.25rem;
    font-weight: 600;
    cursor: pointer;
    display: flex;
    justify-content: space-between;
    align-items: center;
}

button:focus-visible {
    outline: 2px solid var(--focus-outline);
    outline-offset: -2px;
}

/* Chevron icon indicator */
button::after {
    content: '';
    display: inline-block;
    width: 10px;
    height: 10px;
    border-right: 2px solid var(--text-secondary);
    border-bottom: 2px solid var(--text-secondary);
    transform: rotate(45deg);
    transition: transform 0.3s ease;
    margin-left: 1rem;
}

button[aria-expanded="true"]::after {
    transform: rotate(-135deg);
}

.details {
    padding: 0 1.5rem 1rem;
    color: var(--text-secondary);
    border-top: 1px solid var(--border-color);
}

/* JavaScript will toggle the [hidden] attribute */
.details[hidden] {
    display: none;
}

@media (prefers-reduced-motion: reduce) {
    button::after {
        transition: none;
    }
}
