const fs = require('fs');
const path = require('path');

(async () => {
    const browser = await chromium.launch();
    const context = await browser.newContext();
    const page = await context.newPage();

    const htmlPath = path.resolve('index.html');
    const htmlContent = fs.readFileSync(htmlPath, 'utf8');

    // Set content and wait for load
    await page.setContent(htmlContent, { waitUntil: 'load' });

    // Inject CSS
    const cssPath = path.resolve('style.css');
    const cssContent = fs.readFileSync(cssPath, 'utf8');
    await page.addStyleTag({ content: cssContent });

    // Inject JS
    const jsPath = path.resolve('script.js');
    const jsContent = fs.readFileSync(jsPath, 'utf8');
    await page.addScriptTag({ content: jsContent });

    // Inject Axe
    await page.addScriptTag({ path: 'node_modules/axe-core/axe.min.js' });

    const results = await page.evaluate(async () => {
        return await window.axe.run();
    });

    const wcag = results.violations.filter(v => !v.tags.includes('best-practice'));
    const bp = results.violations.filter(v => v.tags.includes('best-practice'));

    console.log(JSON.stringify({
        wcag: wcag.map(v => ({ id: v.id, impact: v.impact, targets: v.nodes.map(n => n.target) })),
        bp: bp.map(v => ({ id: v.id, targets: v.nodes.map(n => n.target) }))
    }, null, 2));

    await browser.close();
    process.exit(wcag.length > 0 ? 1 : 0);
})();
